/* crosswalk cards, r46. */
(window.LADDER_CARDS=window.LADDER_CARDS||{})["46a"]=[{"q": "x = y − b/3 is put into x³ + bx² + cx + d. Which technique is that?", "a": "the shift-out technique", "w": ["the cube-formula technique", "the quartic-to-cubic technique", "the three-real-roots technique"], "why": "The shift clears the square term and leaves y³ + py + q."}, {"q": "y³ + py + q = 0 is solved as u + v with u³, v³ the answers of t² + qt − p³/27 = 0. Which technique?", "a": "the cube-formula technique", "w": ["the shift-out technique", "the three-real-roots technique", "the quartic-to-cubic technique"], "why": "It writes each answer from two cube roots tied by uv = −p/3."}, {"q": "In the cube formula, which tie between the two cube roots is needed?", "a": "uv = −p/3", "w": ["u³v³ = −p³/27 alone", "u = v", "u + v = −q"], "why": "Only the three pairs with uv = −p/3 cancel the 3uv(u + v) term against py."}, {"q": "For y³ − 3y − 1, D = q²/4 + p³/27 = −3/4. How many real answers?", "a": "three different real answers", "w": ["one real answer", "no real answer", "a repeated answer"], "why": "D below 0 is exactly the case of three different real roots."}, {"q": "y³ − 15y − 4 has the answer ∛(2 + 11i) + ∛(2 − 11i). What is that number?", "a": "4", "w": ["2", "−4", "not real"], "why": "(2 + i)³ = 2 + 11i, so the sum is (2 + i) + (2 − i)."}, {"q": "A quartic y⁴ + py² + qy + r is to be split into two quadratics. What must m answer first?", "a": "the cubic q² = 4(2m − p)(m² − r)", "w": ["the quadratic m² = r", "the quartic itself", "the line 2m = p"], "why": "The quartic-to-cubic technique needs one answer of a cubic in m."}, {"q": "Which shift clears the cube term of x⁴ + bx³ + cx² + dx + e?", "a": "x = y − b/4", "w": ["x = y − b/3", "x = y + b", "x = y − b/2"], "why": "Four roots share b equally; a cubic uses b/3."}, {"q": "A line reads √(−3) · √(−3) = √9 = 3. What is wrong?", "a": "(i√3)² = −3, so the product is −3", "w": ["nothing: it is 3", "the product is 9", "√(−3) is not a number"], "why": "The root-choice technique: square roots of negatives do not multiply under one root."}, {"q": "u³ and v³ are found. Of the nine pairs of cube roots u, v, how many give answers of the cubic?", "a": "3", "w": ["9", "1", "6"], "why": "Only the pairs with uv = −p/3, and there are three."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["46b"]=[{"q": "(x − r₁)(x − r₂)(x − r₃) is multiplied out to x³ − e₁x² + e₂x − e₃. Which technique?", "a": "the roots-to-coefficients technique", "w": ["the symmetric-is-coefficients technique", "the symmetric-is-rational technique", "the cubic-discriminant technique"], "why": "The coefficients are the sums of the roots taken one, two and three at a time, with signs."}, {"q": "x₁³ + x₂³ + x₃³ is written as a polynomial in e₁, e₂, e₃. Which technique licenses that?", "a": "the symmetric-is-coefficients technique", "w": ["the roots-to-coefficients technique", "the symmetric-is-rational technique", "the shift-out technique"], "why": "Every symmetric polynomial is one in the sums e₁, …, eₙ."}, {"q": "f has rational coefficients and top coefficient 1. A symmetric expression in its roots comes out rational. Which technique licenses that?", "a": "the symmetric-is-rational technique", "w": ["the symmetric-is-coefficients technique", "the cube-formula technique", "the roots-to-coefficients technique"], "why": "The expression is a polynomial in the coefficients, which are rational."}, {"q": "Is x₁²x₂ + x₂²x₃ + x₃²x₁ symmetric?", "a": "no: a swap changes it", "w": ["yes: every shuffle keeps it", "yes: it is e₁e₂", "no: no shuffle keeps it"], "why": "It is kept by the turns of three and not by the swaps."}, {"q": "Is (r₁ − r₂)(r₁ − r₃)(r₂ − r₃) symmetric?", "a": "no: a swap changes its sign", "w": ["yes, so it is rational", "yes: it is e₃", "no: every shuffle changes it"], "why": "Only its square, the discriminant Δ, is symmetric."}, {"q": "y³ + py + q. What is Δ, the square of the product of root differences?", "a": "−4p³ − 27q²", "w": ["q²/4 + p³/27", "p² − 4q", "4p³ + 27q²"], "why": "The cubic-discriminant technique: Δ = −108 D."}, {"q": "x³ − 2. What is e₃, the product of the three roots?", "a": "2", "w": ["−2", "0", "3"], "why": "The constant is (−1)³e₃ = −2, so e₃ = 2."}, {"q": "x² + bx + c. What is (r₁ − r₂)²?", "a": "b² − 4c", "w": ["b² + 4c", "4c − b²", "b − 2c"], "why": "(r₁ + r₂)² − 4r₁r₂ with r₁ + r₂ = −b and r₁r₂ = c."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["46c"]=[{"q": "A symmetry of ℚ(√2, √3) over ℚ sends √2 to −√2. Which technique forces it to send roots to roots?", "a": "the roots-to-roots technique", "w": ["the count-the-symmetries technique", "the every-root technique", "the symmetric-is-rational technique"], "why": "A symmetry keeps the polynomial’s coefficients, so a root goes to a root."}, {"q": "K is the splitting field of f over F, and [K : F] = 6. How many symmetries does Aut(K/F) have?", "a": "6", "w": ["3", "the number of roots", "6 factorial"], "why": "The count-the-symmetries technique: |Aut(K/F)| = [K : F]."}, {"q": "f is irreducible over F, α and β are roots. Some member of G_f sends α to β. Which technique?", "a": "the every-root technique", "w": ["the roots-to-roots technique", "the count-the-symmetries technique", "the relabel technique"], "why": "Irreducible means the group reaches every root from any one."}, {"q": "How many members has Aut(ℚ(∛2)/ℚ)?", "a": "1", "w": ["3", "2", "6"], "why": "∛2 can only go to a root inside ℚ(∛2), which is real, and the other two are not."}, {"q": "Is the swap of √2 and √3 a symmetry of ℚ(√2, √3)?", "a": "no: it would send 2 to 3", "w": ["yes: both are roots", "yes: it has order 2", "no: it is not undoable"], "why": "(√2)² = 2 must go to (√3)² = 3, but a symmetry fixes 2."}, {"q": "What is the group of x⁴ − 5x² + 6 over ℚ?", "a": "a group of 4", "w": ["S₄, all 24 shuffles", "a group of 8", "a group of 2"], "why": "Its splitting field ℚ(√2, √3) has degree 4."}, {"q": "(1 2 3) is written for a shuffle of three roots. What does it do?", "a": "1 to 2, 2 to 3, 3 to 1", "w": ["swaps 1 and 2, fixes 3", "1 to 3, 3 to 2, 2 to 1", "fixes every root"], "why": "Loop notation: each entry goes to the next, the last to the first."}, {"q": "A map on ℚ(√2) fixes ℚ and sends √2 to 2. Is it a symmetry?", "a": "no: σ(2) would be 4", "w": ["yes", "only if it is undoable", "yes, of order 2"], "why": "σ(2) = σ(√2)² = 4, but σ fixes 2."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["46d"]=[{"q": "H is a part-group of G = Aut(K/F). [K : K^H] = |H|. Which technique?", "a": "the fixed-size technique", "w": ["the middle-field technique", "the normal-middle technique", "the count-the-symmetries technique"], "why": "A part-group fixes a field over which K has degree its size."}, {"q": "H ↦ K^H and E ↦ Aut(K/E) undo each other. Which technique?", "a": "the middle-field technique", "w": ["the fixed-size technique", "the normal-middle technique", "the every-root technique"], "why": "It matches part-groups with middle fields, reversing containment."}, {"q": "K^H is the splitting field of a polynomial over F exactly when H is what?", "a": "normal in G", "w": ["turn-about", "a clock", "of prime size"], "why": "The normal-middle technique, with Aut(K^H/F) matching G/H."}, {"q": "A bigger part-group: does it fix a bigger field?", "a": "no, a smaller one", "w": ["yes", "the same field", "only if normal"], "why": "More symmetries leave fewer members alone; G fixes only F."}, {"q": "K the splitting field of x³ − 2, |G| = 6, H = {e, τ}. What is [K^H : ℚ]?", "a": "3", "w": ["2", "6", "1"], "why": "[E : F] = |G|/|H| = 6/2; |H| = 2 is the climb from K^H to K."}, {"q": "What field does H = {e} fix?", "a": "all of K", "w": ["F only", "nothing", "the roots"], "why": "The identity moves nothing."}, {"q": "ℚ(∛2) sits inside the splitting field of x³ − 2. Is it closed?", "a": "no: its part-group is not normal", "w": ["yes", "yes: it has degree 3", "no: it is not a field"], "why": "Its only symmetry over ℚ is the identity."}, {"q": "Does every field between ℚ and ℂ appear in the matching for one K?", "a": "no: only fields between F and K", "w": ["yes", "only those of degree 2", "only the closed ones"], "why": "The matching is for the middle fields of one splitting field."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["46e"]=[{"q": "A chain {e} ◁ G₁ ◁ ⋯ ◁ G with every step G_(i+1)/G_i turn-about. What is G called?", "a": "solvable", "w": ["simple", "turn-about", "a clock"], "why": "Solvable means a chain with turn-about steps."}, {"q": "N ◁ G with N and G/N solvable. G is solvable. Which technique?", "a": "the solvable-parts technique", "w": ["the pieces technique", "the same-pieces technique", "the not-solvable technique"], "why": "Solvable passes to parts, to quotients, and back."}, {"q": "Two chains of pieces of one group give the same pieces in another order. Which technique?", "a": "the same-pieces technique", "w": ["the pieces technique", "the solvable-parts technique", "the relabel technique"], "why": "Any two chains have the same pieces, the same number of times each."}, {"q": "A group whose only normal part-groups are {e} and itself. What is it called?", "a": "simple", "w": ["solvable", "turn-about", "a clock"], "why": "It cannot be cut by a normal part-group."}, {"q": "ℤ/4 and V both have pieces 2, 2. Are they the same group?", "a": "no", "w": ["yes", "only as sets", "yes, by the same-pieces technique"], "why": "The pieces do not fix the group."}, {"q": "{e, (1 2)(3 4)} ◁ V ◁ S₄. Is {e, (1 2)(3 4)} normal in S₄?", "a": "no", "w": ["yes", "only in A₄", "yes, normal in normal"], "why": "Conjugating by (1 3) gives (3 2)(1 4), outside it."}, {"q": "What are the pieces of ℤ/6?", "a": "clocks of 2 and 3", "w": ["one clock of 6", "clocks of 2, 2, 3", "S₃"], "why": "ℤ/6 has a part-group of 3 with quotient of 2."}, {"q": "A finite group has every piece a clock of prime size. What is it?", "a": "solvable", "w": ["simple", "turn-about", "not solvable"], "why": "The pieces technique: solvable exactly when every piece is a prime clock."}, {"q": "Must a simple group have prime size?", "a": "no: only a turn-about one must", "w": ["yes", "yes, unless it is S₅", "no: every simple group is turn-about"], "why": "43f finds a simple group of 60."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["46f"]=[{"q": "g(1 2 3)g⁻¹ = (g(1) g(2) g(3)). Which technique?", "a": "the relabel technique", "w": ["the families-of-A₅ technique", "the simple-sixty technique", "the every-root technique"], "why": "Conjugating renames the entries of each loop."}, {"q": "Which sizes have the conjugate families of A₅?", "a": "1, 15, 20, 12, 12", "w": ["1, 15, 20, 24", "1, 20, 15, 24", "1, 12, 12, 35"], "why": "The families-of-A₅ technique; the 24 five-loops split in two."}, {"q": "A normal part-group is a union of whole families with the identity. For A₅, no such union divides 60 except 1 and 60. Which technique?", "a": "the simple-sixty technique", "w": ["the families-of-A₅ technique", "the same-pieces technique", "the not-solvable technique"], "why": "So A₅ is simple."}, {"q": "Sₙ is not solvable for n ≥ 5. Which technique?", "a": "the not-solvable technique", "w": ["the simple-sixty technique", "the solvable-parts technique", "the pieces technique"], "why": "A₅ is a simple piece that is not turn-about."}, {"q": "Are (1 2 3) and (1 3 2) conjugate in S₅?", "a": "yes", "w": ["no", "only in A₅", "only if they commute"], "why": "They have the same loop shape."}, {"q": "Do the 24 five-loops make one family in A₅?", "a": "no: two families of 12", "w": ["yes, one of 24", "no: four of 6", "no: 24 of 1"], "why": "In A₅ each has a commuting part of 5, so 60/5 = 12."}, {"q": "A₅ is simple. Is S₅ simple?", "a": "no: A₅ is normal in it", "w": ["yes", "yes: S₅ holds A₅", "no: S₅ is turn-about"], "why": "A₅ ◁ S₅ with half the members."}, {"q": "Is every simple group Aₙ or a clock?", "a": "no: there are others", "w": ["yes", "yes, for sizes under 100", "no: only clocks"], "why": "43·now counts them."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["46g"]=[{"q": "F holds the n-th roots of 1 and aⁿ = c is in F. F(a) over F has a clock as its group. Which technique?", "a": "the root-step technique", "w": ["the turning-sum technique", "the formula-means-solvable technique", "the prime-member technique"], "why": "Each root step has a turn-about group."}, {"q": "f has a formula by roots over F. What follows for G_f?", "a": "it is solvable", "w": ["it is turn-about", "it is simple", "it is Sₙ"], "why": "The formula-means-solvable technique."}, {"q": "F holds the p-th roots of 1 and K over F has a clock of p as its group. K = F(t) with tᵖ in F. Which technique?", "a": "the turning-sum technique", "w": ["the root-step technique", "the solvable-means-formula technique", "the every-root technique"], "why": "The turning sum is a p-th root of something in F."}, {"q": "G_f is solvable. What follows?", "a": "f has a formula by roots", "w": ["f is irreducible", "G_f is turn-about", "f has degree at most 4"], "why": "The solvable-means-formula technique."}, {"q": "p divides |G|. Some member has order p. Which technique?", "a": "the prime-member technique", "w": ["the count-of-parts technique", "the relabel technique", "the root-step technique"], "why": "It finds a member of each prime order dividing the size."}, {"q": "x⁵ − 4x + 2 is irreducible with three real roots. What is its group?", "a": "S₅", "w": ["A₅", "a clock of 5", "a group of 20"], "why": "A five-loop and the flip, a swap, make all of S₅."}, {"q": "An irreducible cubic over ℚ has three real roots. Can a formula by roots stay inside the reals?", "a": "no", "w": ["yes", "only if Δ is a square", "only for whole roots"], "why": "The no-real-route technique."}, {"q": "No formula for x⁵ − 4x + 2. Can its roots be found?", "a": "yes, to any number of places", "w": ["no", "only the real ones", "only one"], "why": "Only a formula by roots is ruled out."}, {"q": "Does no quintic have a formula by roots?", "a": "no: x⁵ − 2 has one", "w": ["yes", "yes, unless it factors", "no: every quintic has one"], "why": "Its group has 20 members and is solvable."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["46h"]=[{"q": "|G| = pᵏ with k ≥ 1. The centre Z(G) has more than one member. Which technique?", "a": "the centre technique", "w": ["the prime-power-chain technique", "the largest-part technique", "the prime-member technique"], "why": "The count by families: family sizes are powers of p, and the centre fills the rest."}, {"q": "A group of size pᵏ has normal part-groups of every size pⁱ in a chain. Which technique?", "a": "the prime-power-chain technique", "w": ["the centre technique", "the largest-part technique", "the pieces technique"], "why": "So every group of prime-power size is solvable."}, {"q": "|G| = 12. Must G have a part-group of size 4?", "a": "yes", "w": ["no", "only if turn-about", "only if it is a clock"], "why": "The largest-part technique: 4 is the largest power of 2 dividing 12."}, {"q": "n_p leaves 1 on the clock of p and divides m. Which technique?", "a": "the count-of-parts technique", "w": ["the largest-part technique", "the centre technique", "the families-of-A₅ technique"], "why": "It also makes any two largest p-parts conjugate."}, {"q": "6 divides 12. Must A₄ have a part-group of size 6?", "a": "no", "w": ["yes", "yes, a largest part", "only if normal"], "why": "6 is not a prime power."}, {"q": "In A₅, n₅ leaves 1 on the clock of 5. Is n₅ = 1?", "a": "no: n₅ = 6", "w": ["yes", "no: n₅ = 5", "no: n₅ = 12"], "why": "24 five-loops, 4 to each part-group of 5."}, {"q": "|G| = 15. What is n₅?", "a": "1", "w": ["3", "6", "5"], "why": "n₅ divides 3 and leaves 1 on the clock of 5."}, {"q": "Is every group of prime-power size turn-about?", "a": "no: the square’s group of 8 is not", "w": ["yes", "yes, by the centre technique", "no: none is"], "why": "A quarter turn and a flip do not commute."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["46i"]=[{"q": "α is constructible. What is [ℚ(α) : ℚ]?", "a": "a power of 2", "w": ["2", "any whole number", "a power of 3"], "why": "The power-of-two technique: each square root at most doubles the degree."}, {"q": "A root of an irreducible cubic over ℚ. Is it constructible?", "a": "no", "w": ["yes", "only if real", "only if Δ is a square"], "why": "The degree-three technique: 3 is not a power of 2."}, {"q": "Aut(K/ℚ) has 2ᵏ members. Every member of K is reached by square roots. Which technique?", "a": "the two-group technique", "w": ["the power-of-two technique", "the prime-power-chain technique", "the seventeen-arcs technique"], "why": "A chain of part-groups of every size 2ⁱ gives a tower of degree-2 steps."}, {"q": "cos(2π/17) is reached by square roots after ℚ(√17). Which technique?", "a": "the seventeen-arcs technique", "w": ["the two-group technique", "the regular-figure technique", "the degree-three technique"], "why": "Its group is a clock of 16 = 2⁴."}, {"q": "Is ∛2 constructible?", "a": "no", "w": ["yes", "yes, by a cube", "only with a straightedge"], "why": "x³ − 2 is irreducible, degree 3."}, {"q": "Is cos 20° constructible?", "a": "no", "w": ["yes", "yes: 60° is", "only its square"], "why": "2 cos 20° is a root of y³ − 3y − 1, irreducible."}, {"q": "[ℚ(α) : ℚ] = 4. Must α be constructible?", "a": "no", "w": ["yes", "yes, by two square roots", "only if real"], "why": "A root of x⁴ − x − 1 has degree 4 and a group of 24."}, {"q": "Can 90° be cut in three?", "a": "yes: cos 30° = √3/2", "w": ["no: no angle can", "only with marks", "no: 30° is not built"], "why": "Some angles can be cut, not all."}, {"q": "cos 72° answers 4c² + 2c − 1 = 0. Is it constructible?", "a": "yes: c = (√5 − 1)/4", "w": ["no", "only its square", "no: degree 4"], "why": "One square root reaches it."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["46j"]=[{"q": "x³ − 7x + 6 has whole coefficients and top coefficient 1. Which numbers can be rational answers?", "a": "whole divisors of 6", "w": ["any fraction u/v", "only 1 and −1", "divisors of 7"], "why": "The whole-answer technique."}, {"q": "D > 0 for y³ + py + q. Which technique gives the answers?", "a": "the one-real technique", "w": ["the third-angle technique", "the whole-answer technique", "the quartic-by-hand technique"], "why": "One real answer, with real cube roots, and a flipped pair."}, {"q": "D < 0 for y³ + py + q. Which technique gives the answers?", "a": "the third-angle technique", "w": ["the one-real technique", "the whole-answer technique", "the shift-out technique"], "why": "Three real answers: k cos(θ/3), k cos(θ/3 − 120°), k cos(θ/3 − 240°)."}, {"q": "Shift, find one m answering q² = 4(2m − p)(m² − r), split into two quadratics. Which technique?", "a": "the quartic-by-hand technique", "w": ["the quartic-to-cubic technique", "the third-angle technique", "the whole-answer technique"], "why": "The recipe for a quartic by hand."}, {"q": "The third-angle technique gives y = k cos(θ/3). Is that the only answer?", "a": "no: θ/3 − 120° and θ/3 − 240° too", "w": ["yes", "no: θ/3 + 90° too", "no: −k cos(θ/3) too"], "why": "All three angles have the same cos 3φ."}, {"q": "Can the third-angle technique be used with D > 0?", "a": "no: |cos θ| > 1", "w": ["yes", "yes, with complex θ only", "only if q = 0"], "why": "No real θ exists."}, {"q": "Is 1/2 a possible root of x³ − 7x + 6?", "a": "no", "w": ["yes", "only if 7 is even", "yes: 1/2 divides 6"], "why": "Top coefficient 1: only whole divisors of 6."}, {"q": "y³ − 12y + 16: D = 64 − 64 = 0. What do the answers do?", "a": "two of them meet", "w": ["all three differ", "none is real", "all three meet"], "why": "D = 0 is the edge: a repeated answer."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["46k"]=[{"q": "Build K one generator at a time, multiply degrees, name symmetries by where generators go. Which technique?", "a": "the group-by-hand technique", "w": ["the fixed-by-hand technique", "the square-discriminant technique", "the count-the-symmetries technique"], "why": "Stop when the count reaches [K : F]."}, {"q": "Find a member that H leaves alone, with field of degree |G|/|H|. Which technique?", "a": "the fixed-by-hand technique", "w": ["the group-by-hand technique", "the fixed-size technique", "the middle-field technique"], "why": "That field is K^H."}, {"q": "An irreducible cubic over ℚ has Δ a rational square. What is its group?", "a": "A₃, the turns of three", "w": ["S₃", "a clock of 2", "all 6 shuffles"], "why": "The square-discriminant technique."}, {"q": "What is the group of x⁴ − 2 over ℚ?", "a": "a group of 8", "w": ["S₄", "a group of 4", "a clock of 4"], "why": "Opposite corners stay opposite: the square’s group."}, {"q": "Is i ↦ 2i a symmetry of ℚ(i)?", "a": "no", "w": ["yes", "only over ℝ", "yes, of order 2"], "why": "i² = −1 would have to go to −4."}, {"q": "Are ℚ(α) and ℚ(iα) the same field, α = ⁴√2?", "a": "no", "w": ["yes", "yes: both have degree 4", "only over ℚ(i)"], "why": "ℚ(α) is real and iα is not."}, {"q": "x³ − 2 has Δ = −108 < 0. How many real roots has it?", "a": "one real root and a flipped pair", "w": ["no real root", "three real roots", "a repeated root"], "why": "∛2 is real."}, {"q": "What is [ℚ(⁴√2, i) : ℚ]?", "a": "8", "w": ["4", "2", "16"], "why": "Degree 4 for ⁴√2, then 2 for i."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["46l"]=[{"q": "Find a polynomial, show it irreducible, check its degree is not a power of 2. Which technique?", "a": "the unbuildable-test technique", "w": ["the power-of-two technique", "the two-group technique", "the regular-figure technique"], "why": "The test for what cannot be built."}, {"q": "cos θ = k rational. θ can be cut in three exactly when 4x³ − 3x − k has a rational root. Which technique?", "a": "the third-of-angle technique", "w": ["the degree-three technique", "the third-angle technique", "the unbuildable-test technique"], "why": "Which angles cut in three."}, {"q": "The regular n-gon can be built exactly when φ(n) is a power of 2. Which technique?", "a": "the regular-figure technique", "w": ["the seventeen-arcs technique", "the power-of-two technique", "the two-group technique"], "why": "Which regular figures."}, {"q": "Can the regular 9-gon be built?", "a": "no: φ(9) = 6", "w": ["yes, because 3 can", "yes: 9 is odd", "no: 9 is not prime"], "why": "A 9-gon needs 40°, a third of 120°."}, {"q": "Can the regular 15-gon be built?", "a": "yes: φ(15) = 8", "w": ["no: 15 is not prime", "no: φ(15) = 15", "only as a star"], "why": "Combine 120° and 72° to reach 24°."}, {"q": "Can the regular 7-gon be built?", "a": "no: φ(7) = 6", "w": ["yes", "yes: 7 is prime", "only with 17"], "why": "6 is not a power of 2."}, {"q": "Does 8x³ − 6x − 1 have the root 1/2?", "a": "no", "w": ["yes", "only if it factors", "yes, the rational root"], "why": "1 − 3 − 1 = −3."}, {"q": "x⁴ − x − 1 has degree 4. Can its roots be built?", "a": "no", "w": ["yes", "yes, by two square roots", "only the real ones"], "why": "Its group is all 24 shuffles."}, {"q": "2³² + 1. Can that many-sided figure be built?", "a": "no: 641 divides it", "w": ["yes: it is prime", "yes: φ is a power of 2 for every n", "no: it is too large"], "why": "641 divides it, and φ(641) = 640 is not a power of 2."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["46·cb27"]=[{"q": "Every representation of a finite group is a sum of whole representations. Which technique?", "a": "the splitting technique", "w": ["the one-stretch technique", "the perpendicular-characters technique", "the pieces technique"], "why": "An averaged inner product gives a kept complement."}, {"q": "V and V′ are whole, T respects G and is not 0. What is T?", "a": "undoable", "w": ["0", "a projection", "a turn-about map"], "why": "The one-stretch technique."}, {"q": "T respects G from a whole V to itself. What is T?", "a": "a multiple of the identity", "w": ["any undoable grid", "0", "a permutation grid"], "why": "The one-stretch technique, second half."}, {"q": "The trace of ρ(g), taken for every g. What is it called?", "a": "the character", "w": ["the determinant", "the size", "the kept line"], "why": "It sorts the pieces."}, {"q": "(1/|G|) Σ χ(g) times the flip of χ′(g) is 0 for two different whole pieces. Which technique?", "a": "the perpendicular-characters technique", "w": ["the one-stretch technique", "the splitting technique", "the fixed-size technique"], "why": "Its proof is held in trust here."}, {"q": "Is the shuffle representation of S₃ on ℂ³ whole?", "a": "no: it keeps the line (t, t, t)", "w": ["yes", "yes: S₃ is simple", "no: it has no kept plane"], "why": "It keeps the line and the plane x + y + z = 0."}, {"q": "Does χ(g) depend on the basis chosen?", "a": "no: trace(PAP⁻¹) = trace(A)", "w": ["yes", "only for a clock", "only if not whole"], "why": "A change of basis is a conjugate."}, {"q": "Water: 9 directions of motion for 3 atoms. How many are shakes?", "a": "3", "w": ["9", "6", "2"], "why": "Three are slides of the whole and three turns of the whole."}, {"q": "A map respecting G between two different whole pieces. What is it?", "a": "0", "w": ["a stretch", "undoable", "the identity"], "why": "Undoable would match them."}];
/* phase F und_r46: understanding cards, appended (ids follow the deck's own) */
(window.LADDER_CARDS["46a"]=window.LADDER_CARDS["46a"]||[]).push(
 {"u":"46a1.1","q":"What is a formula by roots? What does the shift-out technique do to a cubic, and what shift does the same for a quartic?","a":"An expression in the coefficients built by +, −, ×, ÷ and taking n-th roots, finitely often, that gives every answer of every equation of a degree; putting x = y − b/3 into x³ + bx² + cx + d gives a cubic in y with no square term, y³ + py + q; the shift by b/4 takes the cube term out of a quartic","w":["A list of the roots; the shift takes out the constant term; a quartic needs a shift by b/2","A formula with square roots only; the shift x = y + b takes out the y term; a quartic needs no shift","Any expression that gives one answer; the shift doubles the roots; a quartic is shifted by b/3 too"],"why":"x³ − 6x² + 11x − 6 with x = y + 2 becomes y³ − y."},
 {"u":"46a2.1","q":"What does the cube-formula technique say? Why must the cube roots u and v be chosen with uv = −p/3, and not independently?","a":"The answers of y³ + py + q = 0 are u + v, ωu + ω²v and ω²u + ωv, where u³ and v³ are the two answers of t² + qt − p³/27 = 0, the cube roots are chosen with uv = −p/3, and ω is a turn by a third; y = u + v is an answer because the 3uv(u + v) and py terms cancel, and that needs uv = −p/3: knowing only u³v³ = −p³/27 leaves pairs whose product is off by a turn","w":["The answers are u, v and uv; the cube roots may be chosen freely, giving nine answers","The answers are u + v only; uv = −p/3 is needed so that u and v are real","The answers are ∛q and ∛p; uv = −p/3 makes u and v equal"],"why":"For y³ + 3y − 4 the formula writes 1 as ∛(2 + √5) + ∛(2 − √5)."},
 {"u":"46a3.1","q":"What does the three-real-roots technique say? How does the cubic formula reach the real number 2 cos 20° for y³ − 3y − 1 = 0?","a":"y³ + py + q has three different real roots exactly when D = q²/4 + p³/27 is below 0, so exactly then the cubic formula takes the square root of a negative number; here D = −3/4, u³ = ½ + (√3/2)i = cos 60° + i sin 60°, so u = cos 20° + i sin 20° and v = cos 20° − i sin 20°, with uv = 1 = −p/3, and u + v = 2 cos 20°","w":["Three real roots come exactly when D > 0; the formula reaches 2 cos 20° by real cube roots alone","Three real roots come exactly when D = 0; the formula fails for this cubic, and 2 cos 20° is found by guessing","D < 0 means no real root; 2 cos 20° is the size of u, not an answer"],"why":"The other answers are 2 cos 140° and 2 cos 260°."},
 {"u":"46a4.1","q":"What does the quartic-to-cubic technique say? Why does the condition on m have degree 3?","a":"If m is an answer of q² = 4(2m − p)(m² − r) with 2m − p ≠ 0, the quartic y⁴ + py² + qy + r factors into two quadratics, so its four answers come from one cubic and two quadratics; the right side (2m − p)y² − qy + (m² − r) is the square of a line exactly when its discriminant is 0, and that condition multiplies 2m − p, of degree 1 in m, by m² − r, of degree 2","w":["The quartic factors into four lines for every m; the condition has degree 3 because a quartic has three turning points","If m is a root of the quartic it factors; the condition has degree 4","The quartic becomes a quadratic in y²; the condition on m has degree 2"],"why":"y⁴ − 2y² + 8y − 3 with m = 1: (y² − 2y + 3)(y² + 2y − 1)."},
 {"u":"46a5.1","q":"Why do the nine choices of cube roots not give nine answers? Why does D < 0 not mean the cubic has no real answer?","a":"Only the three pairs with uv = −p/3 give answers, and the other six do not; and it is the other way round: D < 0 is exactly when all three answers are real, as for y³ − 3y − 1","w":["They do give nine answers; and D < 0 means no real answer","Because cube roots are unique; and D is never below 0","Because six of the nine are equal; and D < 0 means one real answer"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["46b"]=window.LADDER_CARDS["46b"]||[]).push(
 {"u":"46b1.1","q":"What are the elementary symmetric sums of n roots? What does the roots-to-coefficients technique say about the cubic y³ + py + q?","a":"e₁ is the sum of the roots, e₂ the sum of the products of two different roots, and on to eₙ = r₁r₂⋯rₙ; (x − r₁)⋯(x − rₙ) = xⁿ − e₁xⁿ⁻¹ + e₂xⁿ⁻² − ⋯ + (−1)ⁿeₙ, so for y³ + py + q: e₁ = 0, e₂ = p and e₃ = −q","w":["The sums of the powers of the roots; for the cubic e₁ = p, e₂ = q, e₃ = 0","The roots themselves in order; for the cubic e₁ = 0, e₂ = −p, e₃ = q","The products of all the roots but one; for the cubic every eₖ is 0"],"why":"Each eₖ is unchanged by every shuffle of the roots."},
 {"u":"46b2.1","q":"When is a polynomial in x₁, …, xₙ symmetric? What does the symmetric-is-coefficients technique say, and why does its recipe stop?","a":"When every shuffle of the letters leaves it the same polynomial; every symmetric polynomial is a polynomial in e₁, …, eₙ, with whole coefficients when its own are; the recipe subtracts c times the product of the eₖ whose first term matches, leaving a symmetric polynomial with a later first term, and terms of the same total degree are finitely many, so by the falling-measure technique it stops","w":["When it has equal coefficients; it is then a sum of squares; the recipe stops because degrees fall","When swapping x₁ and x₂ changes its sign; it is a polynomial in e₁ alone; the recipe stops after n steps","When it has no mixed terms; it equals e₁ⁿ; the recipe never stops for whole coefficients"],"why":"x₁² + x₂² + x₃² = e₁² − 2e₂."},
 {"u":"46b3.1","q":"What does the symmetric-is-rational technique say? Why is the sum of the cubes of the roots of x³ − 2 rational though no root is?","a":"If f has rational coefficients and top coefficient 1, every symmetric polynomial with rational coefficients, evaluated at the roots of f, is a rational number: it is a polynomial in the eₖ, which are the coefficients up to sign; the sum of the cubes is symmetric, e₁³ − 3e₁e₂ + 3e₃ = 6 with e₁ = e₂ = 0 and e₃ = 2","w":["Every polynomial in the roots is rational; the sum of cubes is rational because cubes are whole","A symmetric polynomial at the roots is a root again; the sum is 2, one root’s cube","Symmetric quantities are rational only for quadratics; the sum of cubes of the roots of x³ − 2 is not rational"],"why":"A quantity unchanged by some shuffles and not others lives in a field between ℚ and the roots."},
 {"u":"46b4.1","q":"What is the discriminant of a polynomial, and why is it symmetric? What does the cubic-discriminant technique say, and how is it tied to the D of 46a?","a":"Δ is the product of the squared differences of the roots, (rᵢ − rⱼ)² over the pairs i < j, and it is 0 exactly when two roots meet; a shuffle reorders the pairs and changes only signs of differences, which the squares remove; the roots of y³ + py + q have Δ = −4p³ − 27q², which is −108 times D, so D < 0 exactly when Δ > 0","w":["Δ is the sum of the roots; it is symmetric because sums are; for the cubic Δ = D","Δ is the product of the differences, unsquared; it is symmetric because signs cancel; Δ = 108D","Δ is the largest gap between roots; it is not symmetric; for the cubic Δ = p³ + q²"],"why":"For y³ − 3y − 1, Δ = 108 − 27 = 81 = 9²."},
 {"u":"46b5.1","q":"Why is x₁²x₂ + x₂²x₃ + x₃²x₁ not symmetric? Why is the product of the differences of the roots not rational in general, though its square is?","a":"The swap of x₁ and x₂ gives x₂²x₁ + x₁²x₃ + x₃²x₂, a different polynomial: it is kept only by the turns of three; and a swap of two roots changes the sign of the product of the differences, so only its square is symmetric","w":["It is symmetric; and the product of the differences is always rational","Because it has degree 3; and the product is 0","Because its coefficients differ; and the square is never rational"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["46c"]=window.LADDER_CARDS["46c"]||[]).push(
 {"u":"46c1.1","q":"What is the splitting field of f over F? Why is the splitting field of x³ − 2 of degree 6 and not 3?","a":"K = F(r₁, …, rₙ), the smallest field inside ℂ holding F and every root of f; for x³ − 2 the roots are ∛2, ω∛2, ω²∛2, so K = ℚ(∛2, ω): ℚ(∛2) has degree 3 and lies in ℝ, and ω is not real, a root of x² + x + 1, so one step more of degree 2, and degrees multiply up the tower: 3 · 2 = 6","w":["The field F with one root added; it has degree 6 because x³ − 2 has six roots","The largest field holding F; degree 6 because 3! = 6 always","The field of the coefficients; it has degree 3, not 6"],"why":"One root brings in a field of degree 3, and the others need one step more."},
 {"u":"46c2.1","q":"What is a symmetry of K over F? What does the roots-to-roots technique say, and why can a symmetry not send √2 to √3?","a":"A matching σ of K with itself that keeps sums and products and fixes every member of F; a symmetry of the splitting field of f over F sends each root of f to a root of f, and is fixed by what it does to the roots, so Aut(K/F) is a part-group of the shuffles of the roots; σ(√2)² = σ(2) = 2, so σ(√2) is a root of x² − 2, which √3 is not","w":["Any matching of K with itself; a symmetry may send a root anywhere in K; √2 can go to √3 when both are in K","A map that fixes K and moves F; symmetries send roots to coefficients; √2 cannot move at all","A shuffle of the coefficients; it sends each root to itself; √2 goes to √3 by the swap"],"why":"For x² − 2 the group is the identity and the swap of the two roots."},
 {"u":"46c3.1","q":"What does the count-the-symmetries technique say? Why does the proof need an irreducible polynomial to have no repeated root?","a":"If K is the splitting field of a polynomial over F, then Aut(K/F) has exactly [K : F] members; the proof extends a matching one root at a time, and an irreducible factor of degree d gives one extension for each of its roots: it must have d different roots for the count d · [K : F]/d to come out","w":["Aut(K/F) has n! members always; a repeated root would make K larger","Aut(K/F) has at most 2 members; repeated roots are needed for the count","Aut(K/F) has [K : F]² members; the proof does not use irreducible polynomials"],"why":"For x³ − 2 the group has 6 members: all of S₃."},
 {"u":"46c4.1","q":"What is the group of an equation? What does the every-root technique say, and why does the group of x⁴ − 5x² + 6 not send √2 to √3?","a":"G_f is Aut(K/F), with K the splitting field, read as shuffles of the roots; if f is irreducible over F, then for any two roots α and β some member of G_f sends α to β; x⁴ − 5x² + 6 = (x² − 2)(x² − 3) factors, so it is not irreducible: √2 goes to ±√2 and √3 to ±√3, and the group is {e, (1 2), (3 4), (1 2)(3 4)}","w":["The group is all shuffles of the roots; every root goes to every other for any f; √2 goes to √3 in that group","The group is the roots under adding; the every-root technique is for quadratics; √2 and √3 are not roots","The group is Aut(F/K); a member sends α to β only when α = β; the group of x⁴ − 5x² + 6 has 24 members"],"why":"The group keeps the pair {√2, −√2} together: it remembers that f factors."},
 {"u":"46c5.1","q":"Why is there no symmetry of ℚ(√2) sending √2 to 2? Why does ℚ(∛2) have only one symmetry over ℚ?","a":"Then σ(2) = σ(√2)² = 4, but σ fixes 2; and ∛2 can only go to a root of x³ − 2 inside ℚ(∛2), which is real, and the other roots are not: only the identity","w":["There is one; and ℚ(∛2) has three symmetries","Because 2 is not in ℚ(√2); and ℚ(∛2) has no symmetry at all","Because √2 is fixed by every map; and ℚ(∛2) has two, like ℚ(√2)"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["46d"]=window.LADDER_CARDS["46d"]||[]).push(
 {"u":"46d1.1","q":"What is the fixed field of a part-group H, and why is it a field? Why does a bigger part-group have a smaller fixed field?","a":"K^H is the set of a in K with σ(a) = a for every σ in H; if σ fixes a and b it fixes a + b, ab, −a and 1/a, so it is a field between F and K; a bigger part-group asks more symmetries to leave a member alone, so fewer members pass","w":["The members H moves; it is a field because H is a group; a bigger H moves more, so its fixed field is bigger","The field F itself for every H; it is a field by choice; size does not change with H","The set of symmetries in H; it is a field because symmetries compose; bigger H, bigger field"],"why":"The containments go both ways round."},
 {"u":"46d2.1","q":"What does the fixed-size technique say? Why is what every symmetry of K over F leaves alone exactly F?","a":"For every part-group H of G, [K : K^H] = |H|, and Aut(K/K^H) = H; with H = G, K^G is a field E holding F with [K : E] = |G| = [K : F], and degrees multiply up the tower F ⊆ E ⊆ K, so [E : F] = 1 and E = F","w":["[K^H : F] = |H|; the symmetries leave alone all of K","[K : K^H] = |G|/|H|; what they leave alone is larger than F in general","[K : K^H] = 2 for every H; they leave alone only 0 and 1"],"why":"The sizes force equality."},
 {"u":"46d3.1","q":"What does the middle-field technique say? Why is there no middle field of degree 4 over ℚ inside the splitting field of x³ − 2?","a":"H ↦ K^H and E ↦ Aut(K/E) are matchings between the part-groups of G and the middle fields, each undoing the other, with bigger part-groups going to smaller fields, and [E : F] = |G|/|Aut(K/E)|; a middle field of degree 4 would need a part-group of size 6/4, and sizes of part-groups of S₃ divide 6: the six part-groups give the degrees 6, 3, 3, 3, 2 and 1","w":["Every field between ℚ and ℂ matches a part-group; a field of degree 4 exists, fixed by no symmetry","Middle fields match the roots; degree 4 fails because x³ − 2 has three roots","Part-groups match middle fields of the same size; degree 4 is missing because S₃ has no member of order 4"],"why":"Six part-groups, six middle fields, and no others."},
 {"u":"46d4.1","q":"When is a middle field closed? What does the normal-middle technique say, and why is ℚ(∛2) not closed?","a":"When every σ in G sends E onto E; E = K^H is closed exactly when H is normal in G, and then E is the splitting field of a polynomial over F and Aut(E/F) matches the quotient G/H; ℚ(∛2) is fixed by {e, τ}, which is not normal in S₃, and σ sends ∛2 to ω∛2, outside it","w":["When it holds every root; E is closed for every H; ℚ(∛2) is closed, being real","When E = F or E = K; closed fields match part-groups of size 2; ℚ(∛2) is not closed because it has degree 3","When H is the whole group; then Aut(E/F) = H; ℚ(∛2) is not closed because ∛2 is no fraction"],"why":"ℚ(ω) is closed: the splitting field of x² + x + 1."},
 {"u":"46d5.1","q":"Why is the degree of ℚ(∛2) over ℚ not the size of the part-group that fixes it? Why does ℚ(∛2) not have a symmetry group S₃/{e, τ}?","a":"The degree of the fixed field over F is the index |G|/|H| = 3, and |H| = 2 is the climb from it to K; and ℚ(∛2) is not closed: its only symmetry over ℚ is the identity, and the quotient needs H normal","w":["The degree is the size, 2; and its group is S₃/{e, τ}, of size 3","Because τ does not fix ∛2; and S₃ has no quotients","Because ℚ(∛2) is not a field; and {e, τ} is normal"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["46e"]=window.LADDER_CARDS["46e"]||[]).push(
 {"u":"46e1.1","q":"When is a group solvable? Why is V normal in S₄, and why does that make S₄ solvable?","a":"When it has a chain {e} = G₀ ◁ G₁ ◁ ⋯ ◁ Gₖ = G, each a normal part-group of the next, with every quotient turn-about; conjugating a double swap gives a double swap and V holds all of them, so V ◁ S₄, and the chain {e} ◁ V ◁ A₄ ◁ S₄ has quotients of sizes 4, 3, 2, V turn-about and the prime sizes clocks","w":["When it is turn-about; V is normal because it has four members, and S₄ is solvable because 4 divides 24","When every part-group is normal in G; V is normal because it is a clock, which makes S₄ a clock","When its size is a prime power; V is normal because it holds the swaps, so S₄ has quotients 12 and 2"],"why":"Each step need be normal only in the next, not in G."},
 {"u":"46e2.1","q":"What does the solvable-parts technique say? Why is a quotient of a solvable group solvable?","a":"A part-group of a solvable group is solvable, a quotient of a solvable group is solvable, and if N ◁ G with N and G/N solvable then G is solvable; for G/N take the chain GᵢN/N: each of its steps is an image of Gᵢ₊₁/Gᵢ, and an image of a turn-about group is turn-about","w":["Only that part-groups are solvable; a quotient is solvable because it is smaller","That G is solvable when N is; a quotient is solvable because N is turn-about","That solvable groups are turn-about; a quotient of a turn-about group is a clock"],"why":"So being solvable can be read off pieces."},
 {"u":"46e3.1","q":"What is a simple group, and what is a chain of pieces? What does the pieces technique say about the pieces of a solvable group?","a":"A group with more than one member whose only normal part-groups are {e} and itself; a chain {e} = G₀ ◁ ⋯ ◁ Gₖ = G in which every quotient is simple, those quotients being the pieces; every finite group with more than one member has such a chain, and it is solvable exactly when its pieces are all clocks of prime size","w":["A group of prime size; a chain of part-groups normal in G; a solvable group has no pieces","A group with no part-groups but {e} and itself; a chain with turn-about quotients; the pieces of a solvable group are all the same size","A turn-about group; a chain of clocks; a solvable group has one piece"],"why":"A turn-about simple group has prime size."},
 {"u":"46e4.1","q":"What does the same-pieces technique say? How do ℤ/6 and S₃ show that the pieces do not fix the group?","a":"Any two chains of pieces of a finite group have the same pieces, the same number of times each, in some order; ℤ/6 and S₃ both have pieces of sizes 2 and 3, and they are different groups","w":["Every group has one chain of pieces; ℤ/6 and S₃ have different pieces","Two groups with the same pieces match; ℤ/6 and S₃ match","The pieces come in a fixed order; ℤ/6 has 2 then 3 and S₃ has 3 then 2, so they differ"],"why":"Fixed like the primes of a number, but ℤ/4 and V share theirs too."},
 {"u":"46e5.1","q":"Why is {e, (1 2)(3 4)} not normal in S₄ though it is normal in V and V is normal in S₄? Why do turn-about steps not make the group turn-about?","a":"Conjugating (1 2)(3 4) by (1 3) gives (3 2)(1 4), outside it: normal in normal is not normal; and S₃’s steps are turn-about and S₃ is not","w":["It is normal in S₄; and turn-about steps do make the group turn-about","Because it has two members and 2 does not divide 24; and no group has turn-about steps","Because V is not normal in S₄; and S₃ has a step that is not turn-about"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["46f"]=window.LADDER_CARDS["46f"]||[]).push(
 {"u":"46f1.1","q":"When are two members of a group conjugate? What does the relabel technique say, and what does it tell you about a normal part-group of Sₙ?","a":"When y = gxg⁻¹ for some g in G; in Sₙ, g (a₁ a₂ ⋯ aₖ) g⁻¹ = (g(a₁) g(a₂) ⋯ g(aₖ)), so conjugate shuffles have the same loop shape and any two of the same shape are conjugate; a normal part-group holds each member’s whole family, so with one shuffle it holds every shuffle of that shape","w":["When xy = yx; conjugating reverses a loop; a normal part-group holds only even shuffles","When they have the same order; conjugating leaves every loop as it was; a normal part-group holds one shuffle of each shape","When y = gx for some g; conjugate shuffles have different shapes; a normal part-group of Sₙ is a clock"],"why":"In A₅ the g must be even, and a family may split in two."},
 {"u":"46f2.1","q":"What does the families-of-A₅ technique say? Why do the 24 five-loops split into two families in A₅, when the 20 three-loops do not?","a":"The conjugate families of A₅ have sizes 1, 15, 20, 12 and 12; the five members that commute with a five-loop in S₅ are its powers, all even, so its family in A₅ has 60/5 = 12, half the 24; of the six that commute with a three-loop half are odd, leaving 3 in A₅ and a family of 60/3 = 20, all of them","w":["The families have sizes 1, 15, 20 and 24; the five-loops do not split","The families have sizes 1, 20, 15, 12, 12; the five-loops split because 24 does not divide 60, and the three-loops do not because 20 is even","The families all have 12 members; the five-loops split because half of them are odd"],"why":"A family has |H|/|C(x)| members."},
 {"u":"46f3.1","q":"What does the simple-sixty technique say, and which two facts does its count use? Why is A₅ not turn-about?","a":"A₅ is simple; a normal part-group is a union of families with e, so its size is 1 plus some of 15, 20, 12, 12, and its size divides 60, and of all those sums only 1 and 60 divide 60; and (1 2 3)(3 4 5) sends 2 to 3 while (3 4 5)(1 2 3) sends 2 to 4, so they differ","w":["A₅ is solvable; it uses that 60 is even and that 5 is prime; A₅ is not turn-about because it has 60 members","A₅ is simple; it uses that A₅ has half of S₅ and that S₅ is simple; A₅ is not turn-about because it is simple","A₅ has no part-groups; it uses the same-pieces technique and the relabel technique; A₅ is turn-about"],"why":"The sums are 1, 13, 16, 21, 25, 28, 33, 36, 40, 45, 48, 60."},
 {"u":"46f4.1","q":"What does the not-solvable technique say? Why does A₅ being simple and not turn-about stop it being solvable?","a":"A₅ is not solvable, and Sₙ is not solvable for any n ≥ 5; A₅ being simple, its one chain of pieces is {e} ◁ A₅ with the piece A₅, which is not a clock of prime size since it is not turn-about, and a solvable group’s pieces are all clocks of prime size","w":["Sₙ is not solvable for any n; A₅ is not solvable because 60 is not prime","A₅ is solvable and S₅ is not; A₅ being simple gives it a chain of clocks","Sₙ is simple for n ≥ 5; A₅ is not solvable because it has too many families"],"why":"Sₙ for n ≥ 5 holds a copy of A₅, and a part of a solvable group is solvable."},
 {"u":"46f5.1","q":"Why do the five-loops make two families in A₅? Why is S₅ not simple?","a":"In A₅ the part that commutes with a five-loop is all even, so the family has 60/5 = 12 of the 24; and A₅ ◁ S₅, with half the members","w":["They make one family of 24; and S₅ is simple because A₅ is","Because 24 is not prime; and S₅ is not simple because it is turn-about","Because half the five-loops are odd; and S₅ is not simple because V is normal in it"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["46g"]=window.LADDER_CARDS["46g"]||[]).push(
 {"u":"46g1.1","q":"What is a tower of roots, and when does f have a formula by roots? What does the root-step technique say, and why does it need the n-th roots of 1 to be in F already?","a":"A chain F = F₀ ⊆ F₁ ⊆ ⋯ ⊆ Fₖ in ℂ with Fᵢ₊₁ = Fᵢ(aᵢ) and some power aᵢ^(nᵢ) in Fᵢ; f has a formula by roots when its splitting field lies inside the top of some tower; adjoining the n-th roots of 1 gives a turn-about group, and if F holds them and aⁿ = c is in F then F(a) is the splitting field of xⁿ − c with a clock for its group; the roots are a, ζa, …, ζⁿ⁻¹a, so with ζ in F they all lie in F(a) and each symmetry is fixed by the power k with σ(a) = ζᵏa","w":["A chain of groups; f has a formula when its group is a clock; adjoining a root always gives a clock, with or without the roots of 1","A chain of fields each of degree 2; f has a formula when its roots are real; the roots of 1 are needed so that c is positive","A chain of polynomials; f has a formula when it is irreducible; the roots of 1 are needed so that F(a) is larger than F"],"why":"Each root in a formula adds one floor."},
 {"u":"46g2.1","q":"What does the formula-means-solvable technique say? Why does the proof enlarge the tower to L, and why does it adjoin the roots of 1 first?","a":"If f has a formula by roots over F, then G_f is solvable; the top of the tower need not be closed, so the proof takes L, a splitting field over F holding every σ(aᵢ), so that the matching and the normal-middle technique apply; and with ζ_N adjoined first, each later floor is a root step over a field that holds the roots of 1, so its group is turn-about","w":["If G_f is solvable, f has a formula; L is taken to make the tower shorter; the roots of 1 are adjoined to make L real","If f has a formula, G_f is a clock; L is taken because K is not a field; the roots of 1 are adjoined last","If f has a formula, G_f is simple; L is taken to remove the roots aᵢ; the roots of 1 are not used"],"why":"Then G_f is a quotient of Aut(L/F), and a quotient of solvable is solvable."},
 {"u":"46g3.1","q":"What does the turning-sum technique say? Why is tᵖ in F, and why is t not in F?","a":"If F holds the p-th roots of 1 and K over F is a splitting field whose group is a clock of prime size p, then K = F(t) with tᵖ in F; σ(t) = ζt, so σ(tᵖ) = ζᵖtᵖ = tᵖ, fixed by the whole group and so in F; and t ≠ 0 with σ(t) = ζt ≠ t, so t is moved and is not in F","w":["That every field is F(t); tᵖ is in F because p is prime; t is not in F because it is not real","That K = F(t) with t in F; tᵖ is in F because t is; t is in F","That the turning sum is always 0; tᵖ is in F because σ(t) = t; t is not in F because ζ is not"],"why":"Some α must be chosen with t ≠ 0."},
 {"u":"46g4.1","q":"What does the prime-member technique say? Why does x⁵ − 4x + 2 have a swap and a five-loop in its group?","a":"If a prime p divides the size of a finite group, some member has order p; the quintic has three real roots and two that are not real, and the flip swaps those two, a swap in G_f; and it is irreducible of degree 5, so 5 divides |G_f|, and a member of order 5 among the shuffles of five is a five-loop","w":["Every member has prime order; the swap comes from the two real roots and the five-loop from the five real roots","If p divides |G| then G is a clock of p; the swap and the loop come from the formula for the roots","Some member has order |G|; the group has a swap because 2 divides −4, and a five-loop because the roots are evenly spaced"],"why":"A five-loop and a swap make every shuffle of five, so G_f = S₅."},
 {"u":"46g5.1","q":"What does the no-real-route technique say? Why must the last floor of a real tower, the one that first holds a root, have degree 3?","a":"An irreducible cubic over ℚ with three real roots has no formula by roots inside the reals; f has no root in F, so it is irreducible over F and 3 = [F(r) : F] divides [F(a) : F], which is at most the prime p, so p = 3 and F(a) = F(r)","w":["No cubic has a formula by roots; the floor has degree 3 because the cubic has three roots in F","A cubic with three real roots has a real formula; the floor has degree 2","An irreducible cubic has no real roots; the floor has degree 3 because √Δ is in F"],"why":"Then ωa would lie in a real field."},
 {"u":"46g6.1","q":"Why does “no formula by roots” not mean the roots of x⁵ − 4x + 2 cannot be found? Why does some quintic have a formula by roots?","a":"The roots exist and are found to any number of places; only a formula by roots is ruled out; and x⁵ − 2 has one: its roots are ζᵏ · ⁵√2, and its group has 20 members, solvable","w":["It does mean that; and no quintic has a formula by roots","The roots can be found only when they are real; and every quintic with real roots has a formula","The roots do not exist; and x⁵ − 4x + 2 itself has a formula over ℂ"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["46h"]=window.LADDER_CARDS["46h"]||[]).push(
 {"u":"46h1.1","q":"What is the centre of a group? What does the centre technique say, and why must p divide |Z(G)|?","a":"The set of members that commute with every member; if |G| = pᵏ with p prime and k ≥ 1, then Z(G) has more than one member; |G| is |Z(G)| plus the sizes of the families of more than one member, each a power of p above 1, so p divides |G| and every one of those terms, and so divides |Z(G)|","w":["The identity alone; the centre of a group of size pᵏ is the whole group; p divides |Z(G)| because Z(G) is a clock","The members of order p; the centre has exactly p members; p divides it because p is prime","The largest normal part-group; the centre is {e} when |G| = pᵏ; p does not divide |Z(G)|"],"why":"The square’s group of 8 has centre {e, half turn}."},
 {"u":"46h2.1","q":"What does the prime-power-chain technique say? Why is the first step N of the chain normal in G?","a":"A group of size pᵏ has a chain {e} = G₀ ◁ G₁ ◁ ⋯ ◁ Gₖ = G with |Gᵢ| = pⁱ and each Gᵢ normal in G, so it is solvable and has part-groups of every size pⁱ; N is made of the powers of a z in the centre, and z commutes with everything, so gNg⁻¹ = N","w":["A group of size pᵏ is a clock; N is normal because it has p members","A group of size pᵏ is simple; N is normal because G/N is turn-about","A group of size pᵏ has one part-group; N is normal because every part-group of any group is"],"why":"Each step has size p, a clock."},
 {"u":"46h3.1","q":"What is a largest p-part of G? What does the largest-part technique say, and what does the proof do when p does not divide |Z(G)|?","a":"With |G| = pᵃm and p not dividing m, a part-group of size pᵃ; every finite group has one for every prime p, and so has a part-group of every prime-power size that divides its size; when p does not divide |Z(G)|, some family size |G|/|C(x)| is not divisible by p, so pᵃ divides |C(x)|, a smaller group, which has a part-group of size pᵃ by induction","w":["A part-group of size p; only turn-about groups have one; the proof then takes the quotient by the centre","The largest normal part-group; every group has exactly one; the proof stops, since there is none","A part-group of size m; every group has one for each prime; the proof then takes N made of a member of order p in the centre"],"why":"When p does divide |Z(G)|, the proof goes through G/N."},
 {"u":"46h4.1","q":"What does the count-of-parts technique say? Why does every group of 15 members have one part-group of size 3 and one of size 5?","a":"Any two largest p-parts are conjugate, and their number n_p leaves 1 on the clock of p and divides m; for 15 = 3 · 5, n₃ divides 5 and leaves 1 on the clock of 3, and 5 leaves 2, so n₃ = 1; n₅ divides 3 and leaves 1 on the clock of 5, and 3 leaves 3, so n₅ = 1","w":["That n_p = 1 always; a group of 15 has one of each because 15 is odd","That n_p divides p; a group of 15 has five of size 3 and three of size 5","That largest p-parts are normal; a group of 15 has one of each because it is simple"],"why":"So every group of 15 members is a clock."},
 {"u":"46h5.1","q":"Why does 6 dividing 12 not give A₄ a part-group of size 6? Why does n_p leaving 1 on the clock of p not mean n_p = 1?","a":"6 is not a prime power, and A₄ has no part-group of size 6; and in A₅, n₅ = 6, which leaves 1 on the clock of 5","w":["It does give one; and n_p leaving 1 does mean n_p = 1","Because 6 is even; and n_p is never 1","Because A₄ is simple; and in A₅, n₅ = 5"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["46i"]=window.LADDER_CARDS["46i"]||[]).push(
 {"u":"46i1.1","q":"When is a real number constructible? What does the power-of-two technique say, and which technique of 18j gives its first line?","a":"When the tools of 18j, started from (0, 0) and (1, 0), reach a point with it as a coordinate; a constructible number α has [ℚ(α) : ℚ] a power of 2; the first line, one floor Kᵢ(√kᵢ) for each point marked, comes from the root-and-ratio technique of 18j5","w":["When it is rational; a constructible number has degree 2; the perpendicular technique","When it is a root of a polynomial over ℚ; its degree is a power of 3; the midpoint technique","When it has a square root; every number of degree a power of 2 is constructible; the drawn-root technique"],"why":"Each floor has degree 1 or 2, and degrees multiply up the tower."},
 {"u":"46i2.1","q":"What does the degree-three technique say? Why does cutting the angle of 60° in three come down to the cubic y³ − 3y − 1?","a":"A root of an irreducible cubic over ℚ is not constructible, its field having degree 3, which is not a power of 2; cos 3θ = 4cos³θ − 3cos θ at θ = 20° gives 4c³ − 3c = 1/2, and y = 2c turns that into y³ − 3y − 1 = 0, which has no rational root since ±1 are not roots","w":["No cubic has constructible roots; the cubic comes from cos 60° = 3 cos 20°","A root of a cubic has degree 2; the cubic comes from the volume of a cube","Every cubic root is constructible when real; y³ − 3y − 1 comes from the seventh roots of 1"],"why":"So cos 20° is not constructible."},
 {"u":"46i3.1","q":"What does the two-group technique say? Why does each floor of the tower add exactly one square root?","a":"If K is a splitting field over ℚ and Aut(K/ℚ) has 2ᵏ members, every member of K is reached from ℚ by square roots; the chain of part-groups of sizes 2ⁱ gives fixed fields each of degree 2 over the next, and a floor E(β) of degree 2 has β² + bβ + c = 0 with b, c in E, so E(β) = E(√(b² − 4c))","w":["Every field of degree a power of 2 is reached by square roots; each floor adds a square root because 2 is prime","If the group has 2ᵏ members the field is ℚ; no floor adds anything","A group of 2ᵏ members is a clock; each floor adds a cube root"],"why":"The chain is the prime-power-chain technique, the fields the middle-field technique."},
 {"u":"46i4.1","q":"What does the seventeen-arcs technique say? Why is the group of ℚ(ζ) over ℚ a clock with 16 members, and why does that make the 17-gon constructible?","a":"cos(2π/17) is constructible, reached by three square-root steps after ℚ(√17); a symmetry sends ζ to ζᵏ for some k from 1 to 16, so the group is the clock group of the units of 17, and 3 reaches every hour of it; 16 = 2⁴, so the two-group technique reaches ζ and 2cos(2π/17) = ζ + ζ¹⁶ by square roots","w":["cos(2π/17) is rational; the group has 17 members, one for each root; 17 is prime, so the figure is constructible","cos(2π/17) is not constructible; the group has 16 members and 16 is not prime","cos(2π/17) is reached by one square root; the group is S₁₇; every group of even size gives square roots"],"why":"The first step is x² + x − 4, with roots (−1 ± √17)/2."},
 {"u":"46i5.1","q":"Why does a degree of 4 not make a number constructible? Why does the degree-three technique not forbid cutting 90° in three?","a":"A power of 2 is needed, and it is not enough: a root of x⁴ − x − 1 has degree 4 and a group of 24; and 90° can be cut in three, since cos 30° = √3/2","w":["A degree of 4 does make it constructible; and 90° cannot be cut in three","Because 4 is not a power of 2; and 90° is not an angle of a triangle","Because only degree 2 is allowed; and 30° is found with a marked straightedge"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["46j"]=window.LADDER_CARDS["46j"]||[]).push(
 {"u":"46j1.1","q":"What does the whole-answer technique say? Why are x³ − 7x + 6’s answers found here without the formula?","a":"If a cubic or quartic has whole coefficients and top coefficient 1, every rational answer is a whole number dividing the last coefficient; trying the divisors of 6 gives x = 1, division leaves x² + x − 6 = (x − 2)(x + 3), so the answers are 1, 2, −3; with D < 0 the formula would have reached them through cube roots of numbers in the plane","w":["Every answer of a cubic is whole; the formula does not apply to x³ − 7x + 6","A rational answer divides the top coefficient; the answers are found by the third-angle technique","Whole answers are the divisors of 7; the formula gives the wrong answers here"],"why":"Try divisors first."},
 {"u":"46j2.1","q":"What does the one-real technique say? For x³ + 6x − 20, why is uv = −2 a check that the right cube roots were chosen?","a":"If D > 0, the cubic y³ + py + q has one real answer, ∛(−q/2 + √D) + ∛(−q/2 − √D), with real cube roots, and two answers that are flips of each other; the cube roots must have uv = −p/3, and here p = 6, so uv = (1 + √3)(1 − √3) = −2 is what the formula needs","w":["If D > 0 there are three real answers; uv = −2 because q = −20","If D > 0 there is no real answer; uv = −2 checks that u = v","If D < 0 the answer is u + v; uv = −2 is half of p"],"why":"The answers are 2 and −1 ± 3i."},
 {"u":"46j3.1","q":"What does the third-angle technique say? Why does D < 0 make |cos θ| < 1?","a":"If D < 0, put k = 2√(−p/3) and cos θ = (3q / 2p)·√(−3/p); the three answers of y³ + py + q = 0 are k cos(θ/3), k cos(θ/3 − 120°) and k cos(θ/3 − 240°); putting y = kc turns the cubic into 4c³ − 3c = −4q/k³, and D < 0 says exactly that this number lies strictly between −1 and 1","w":["If D > 0 the answers are cosines; |cos θ| < 1 for every cubic","If D < 0 there is one answer, k cos θ; |cos θ| < 1 because p is positive","If D = 0 the answers are k cos(θ/3); D < 0 makes cos θ larger than 1"],"why":"Three values of φ have cos 3φ = cos θ; the rest repeat."},
 {"u":"46j4.1","q":"What does the quartic-by-hand technique say? Why is it worth trying whole answers of the cubic in m first?","a":"Shift out the cube term, find one answer m of q² = 4(2m − p)(m² − r), and split (y² + m)² less a square into two quadratics; any one answer m with 2m − p ≠ 0 does, and a whole one, such as m = 1 for y⁴ + y² + 4y − 3, makes both squares exact and the two quadratics easy","w":["Shift by b/3 and take a cube root; whole answers are tried because the cubic has no others","Find all three answers m and add them; whole answers are tried because non-real ones give different roots","Factor the quartic into four lines by guessing; the cubic in m is not needed"],"why":"A non-real m would give the same four roots by a longer road."},
 {"u":"46j5.1","q":"Why can 1/2 not be a root of x³ − 7x + 6? Why does the third-angle technique fail when D > 0?","a":"The top coefficient is 1, so a rational root is a whole divisor of 6; and when D > 0, |cos θ| > 1 and no real θ exists","w":["1/2 is a root; and the technique works for every D","Because 1/2 is not real; and when D > 0 the angle is 0","Because 2 does not divide 7; and when D > 0 there are three angles too many"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["46k"]=window.LADDER_CARDS["46k"]||[]).push(
 {"u":"46k1.1","q":"What does the group-by-hand technique say, in its four moves? Why does ω have two choices on the second floor of x³ − 2?","a":"Find the roots; build K one generator at a time and multiply the degrees; name symmetries by where they send the generators, each to a root of its own polynomial over the floor below; stop when the count reaches [K : F]; ω’s polynomial over ℚ(∛2) is x² + x + 1, with the two roots ω and ω²","w":["Guess the group, list its part-groups, find their fields, check; ω has two choices because 2 divides 6","Find the roots, shuffle them every way, count the shuffles, stop at n!; ω has three choices","Find the discriminant, take its root, adjoin it, stop; ω has one choice since it is fixed"],"why":"3 · 2 = 6 symmetries: S₃."},
 {"u":"46k2.1","q":"Why does the splitting field of x⁴ − 2 have degree 8? Why is the group of x⁴ − 2 the square’s group of 8, and not all 24 shuffles of the roots?","a":"K = ℚ(α, i) with α = ⁴√2: x⁴ − 2 is irreducible, so ℚ(α) has degree 4, and i is not in the real field ℚ(α), a root of x² + 1, degree 2: 4 · 2 = 8; a symmetry is fixed by sending α to one of four roots and i to ±i, eight in all, and r: α ↦ iα and s: i ↦ −i have r⁴ = e, s² = e, srs = r⁻¹, the turn and flip of the square of roots","w":["Because 4 · 2 = 8 roots; the group has 8 members because 8 divides 24","Because x⁴ − 2 has degree 8 over ℚ(i); the group is the square’s because the roots are real","Because K = ℚ(α) and α has degree 8; the group is a clock of 8"],"why":"The count equals [K : ℚ], so there are no more."},
 {"u":"46k3.1","q":"What does the fixed-by-hand technique say? Why is ℚ(√2) fixed by {e, r², s, r²s}, and why is ℚ(α) not closed?","a":"To find the field fixed by a part-group H, find a member of K that H leaves alone and whose field has degree |G|/|H|; that field is K^H; r² and s both fix α² = √2, and ℚ(√2) has degree 2 = 8/4; ℚ(α) is not closed because r sends α to iα, outside it","w":["Take the field of all members H moves; ℚ(√2) is fixed because √2 is rational; ℚ(α) is closed","Find any member H fixes, of any degree; ℚ(√2) is fixed by r; ℚ(α) is not closed because it has degree 4","The fixed field is always ℚ; ℚ(√2) is fixed by every symmetry; ℚ(α) is not a field"],"why":"Ten middle fields in all."},
 {"u":"46k4.1","q":"What does the square-discriminant technique say? Why does a swap of two roots change the sign of δ?","a":"An irreducible cubic over ℚ has group A₃ when its discriminant Δ is the square of a rational number, and S₃ when it is not; δ is the product of the three differences of roots, and a swap, an odd shuffle, changes the sign of an odd number of the factors","w":["The group is S₃ when Δ is a square; a swap changes δ because it changes Δ","The group is A₃ when Δ < 0; a swap changes the sign of two factors","Every cubic has group S₃; a swap leaves δ alone"],"why":"y³ − 3y − 1 has Δ = 81 = 9²; x³ − 2 has Δ = −108."},
 {"u":"46k5.1","q":"Why is the group of x⁴ − 2 not all of S₄? Why are ℚ(α) and ℚ(iα) different fields?","a":"A symmetry keeps sums: α + (−α) = 0 must go to a root plus its negative, so opposite corners stay opposite; and the two fields are fixed by different part-groups: ℚ(α) is real, and iα is not","w":["It is all of S₄; and the two fields are the same","Because 4 is not prime; and the fields have different degrees","Because i is not a root; and ℚ(iα) is not a field"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["46l"]=window.LADDER_CARDS["46l"]||[]).push(
 {"u":"46l1.1","q":"What does the unbuildable-test technique say, in its three moves? Why does the 9-gon come down to y³ − 3y + 1?","a":"Find a polynomial with rational coefficients the number is a root of, show it irreducible, and check that its degree is not a power of 2; a 9-gon needs 40°, and with c = cos 40°, 4c³ − 3c = cos 120° = −1/2, so y = 2c has y³ − 3y + 1 = 0, with no rational root, so irreducible of degree 3","w":["Draw it, measure it, compare; the 9-gon comes from y² + y − 1","Find its decimal, round it, test it; the 9-gon comes from cos 60°","Find a polynomial, factor it, count the factors; the 9-gon comes down to x⁹ − 1 being irreducible"],"why":"So 120° cannot be cut in three either."},
 {"u":"46l2.1","q":"What does the third-of-angle technique say? Why can 90° be cut in three though 60° cannot?","a":"An angle whose cosine k is buildable can be cut in three exactly when 4x³ − 3x − k has a root in ℚ(k)’s tower of square roots, and for rational k exactly when it has a rational root; for 90°, k = 0 and 4x³ − 3x = x(4x² − 3) has the root √3/2 = cos 30°, a square root; for 60°, 8x³ − 6x − 1 has no rational root","w":["Every angle with a rational cosine can be cut in three; 60° cannot because its cosine is not rational","No angle can be cut in three; 90° is cut only with marks","An angle can be cut in three when it is a multiple of 9°; 60° is not"],"why":"With no rational root the cubic is irreducible and the degree is 3."},
 {"u":"46l3.1","q":"What does the regular-figure technique say? Why can the 15-gon be built though the 9-gon cannot?","a":"The regular n-gon can be built exactly when φ(n) is a power of 2; φ(15) = 8, a power of 2, and φ(9) = 6, which is not","w":["The n-gon can be built exactly when n is prime; 15 is built because 3 and 5 are","The n-gon can be built exactly when n is a power of 2; neither can be built","The n-gon can be built when φ(n) is even; both can be built"],"why":"n is a power of 2 times different primes of the form 2^(2^m) + 1."},
 {"u":"46l4.1","q":"How does 2 cos 72° come out of the fifth roots of 1? In the construction, why is OP equal to (√5 − 1)/2?","a":"Dividing 1 + ζ + ⋯ + ζ⁴ = 0 by ζ² and putting y = ζ + ζ⁻¹ = 2 cos 72° gives y² + y − 1 = 0, whose positive root is (−1 + √5)/2; in the construction MA = √(1 + 1/4) = √5/2, the circle about M through A gives MP = √5/2, and MO = 1/2, so OP = √5/2 − 1/2","w":["From ζ⁵ = 1 directly, y = 1/5; OP is measured with marks","From y³ − 3y − 1 = 0; OP = MA + MO","From the fourth roots of 1; OP is half of OA"],"why":"So cos 72° = (√5 − 1)/4."},
 {"u":"46l5.1","q":"Why does a degree of 4 not let the roots of x⁴ − x − 1 be built? Why does the 3-gon being buildable not make the 9-gon buildable?","a":"Its group is all 24 shuffles; 24 is not a power of 2, and the two-group technique fails; and φ(9) = 6: a 9-gon needs 40°, a third of 120°","w":["A degree of 4 does let them be built; and the 9-gon can be built","Because the roots are not real; and 9 is not prime","Because 4 is not a power of 2; and φ(9) = 8"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["46·cb27"]=window.LADDER_CARDS["46·cb27"]||[]).push(
 {"u":"46·cb27.1.1","q":"What is a representation of a group, and when is a space kept by it? Why does the shuffle representation of S₃ keep the line of vectors (t, t, t)?","a":"A map ρ from G to the undoable n × n grids with ρ(gh) = ρ(g)ρ(h); a space W inside V is kept when ρ(g) sends W into W for every g; a shuffle moves the three entries of a vector among themselves, and shuffling entries that are all equal leaves them all equal","w":["A list of the members of G; a space is kept when one ρ(g) fixes it; the line is kept because its vectors add to 0","A map from grids to G; a space is kept when it has dimension 1; the line is kept because S₃ is turn-about","A part-group of G; a space is kept when ρ(g) sends it to 0; the line is kept because (t, t, t) has length 1"],"why":"It keeps the plane x + y + z = 0 too."},
 {"u":"46·cb27.2.1","q":"What does the splitting technique say? Why does the averaged inner product make the perpendicular of a kept space kept?","a":"Every representation of a finite group is a sum of whole representations; the averaged inner product is unchanged by every ρ(h), so for v perpendicular to W and w in W, ⟨ρ(h)v, w⟩ = ⟨v, ρ(h⁻¹)w⟩ = 0, since ρ(h⁻¹)w is in W","w":["Every representation is whole; the perpendicular is kept because it is smaller","Every representation of any group splits; the perpendicular is kept because the grids stretch","A representation splits only for turn-about groups; the average makes every space kept"],"why":"Split again until every piece is whole; the dimension falls each time."},
 {"u":"46·cb27.3.1","q":"When does a straight map respect G? What does the one-stretch technique say, and why does it make every whole representation of a turn-about group one-dimensional?","a":"When T ρ(g) = ρ′(g) T for every g; if V and V′ are whole and T respects G, then T is 0 or undoable, and if V′ = V then T is a multiple of the identity; in a turn-about group every ρ(h) respects G, so each is a multiple of the identity, every line is kept, and a whole piece can only be one line","w":["When T is undoable; a respecting map is always 0; a turn-about group has no whole pieces","When T commutes with one ρ(g); T is a turn; the pieces are one-dimensional because the group is finite","When T ρ(g) = 0; T is the identity; the pieces are one-dimensional because every grid is 1 × 1 to begin with"],"why":"What T loses and what it reaches are both kept."},
 {"u":"46·cb27.4.1","q":"What is the character of a representation, and why is it the same on a conjugate family? How does the table of S₃ show that ℂ³ is one copy of the one representation and one of W?","a":"χ(g) is the trace of ρ(g), the sum of its main diagonal; trace(AB) = trace(BA), so trace(ρ(h)ρ(g)ρ(h)⁻¹) = trace ρ(g); the character of ℂ³ counts fixed points, (3, 1, 0), and that is (1, 1, 1) + (2, 0, −1), the characters of the one representation and of W","w":["χ(g) is the determinant of ρ(g); it is the same because families have one member; ℂ³ is three copies of the one representation","χ(g) is the order of g; it is the same on a family because conjugates commute; (3, 1, 0) is the sign plus W","χ(g) is the size of g’s family; ℂ³ is W twice, since 2 + 2 = 4"],"why":"And 1² + 1² + 2² = 6 = |S₃|."},
 {"u":"46·cb27.5.1","q":"What are the four symmetries of a water molecule, and why is each whole piece of dimension 1? How does the character (9, −1, 3, 1) give three shakes?","a":"The identity, the half turn about the line that halves the angle, the flip across the molecule’s plane, and the flip across the plane that holds the axis and is perpendicular to the molecule; the group is turn-about, so its whole pieces have dimension 1; projecting the character gives 3 A₁, 1 A₂, 3 B₁, 2 B₂, and taking away the slides of the whole, A₁ + B₁ + B₂, and the turns of the whole, A₂ + B₁ + B₂, leaves 2A₁ + B₁: three shakes","w":["Three turns by 120° and the identity; the pieces are of dimension 1 because water has three atoms; 9 − 6 = 3 by counting atoms","Two flips only; the pieces have dimension 2; the character gives 9 shakes","The identity and the half turn; each piece is of dimension 1 because the molecule is bent; the shakes are 9 − 1 − 3 − 1 = 4"],"why":"Measured at 1595, 3657 and 3756 waves per centimetre."},
 {"u":"46·cb27.6.1","q":"Why is the shuffle representation of S₃ on ℂ³ not whole? Why does the character not depend on the basis chosen?","a":"It keeps the line (t, t, t) and the plane x + y + z = 0; and trace(PAP⁻¹) = trace(A): a change of basis is a conjugate","w":["It is whole; and the character does depend on the basis","Because S₃ is not turn-about; and the character is always 1","Because ℂ³ has dimension 3; and the basis is fixed by the group"],"why":"Both are rows of the step’s Moves to Watch Out For."});
