(function(C){C["46f"]=(C["46f"]||[]).concat([{"q": "Do the 24 five-loops make one family in A₅?", "a": "no: in A₅ they make two families of 12", "w": ["yes", "no: five families", "yes, of 24"], "why": "Families-of-A₅ technique."}, {"q": "Could the twelve five-loops of one family be a normal part-group of A₅?", "a": "no: it has no identity, and 12 + 1 = 13 does not divide 60", "w": ["yes", "yes, of size 12", "only with the identity"], "why": "Simple-sixty technique."}, {"q": "For which n is Sₙ not solvable?", "a": "every n ≥ 5", "w": ["no n", "every n ≥ 3", "only n = 5"], "why": "Not-solvable technique."}, {"q": "What does conjugating a shuffle do to its loops?", "a": "relabels them, so the loop shape stays", "w": ["reverses them", "breaks them", "joins them"], "why": "Relabel technique."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
