(function(C){C["46i"]=(C["46i"]||[]).concat([{"q": "[ℚ(α) : ℚ] = 4. Is α constructible?", "a": "not necessarily: a power of 2 is needed, not enough", "w": ["yes, by the power-of-two technique", "yes", "no: never"], "why": "Power-of-two technique runs one way."}, {"q": "Is a root of an irreducible cubic over ℚ constructible?", "a": "no", "w": ["yes", "yes, if real", "only for x³ − 2"], "why": "Degree-three technique."}, {"q": "How is the 17-sided figure built?", "a": "three square-root steps after ℚ(√17)", "w": ["by a cube root", "it cannot be", "by marking the straightedge"], "why": "Seventeen-arcs technique."}, {"q": "Is the circle not squared because π has degree 3?", "a": "no: π is a root of no polynomial over ℚ at all", "w": ["no: π has degree 2", "yes", "yes, by the degree-three technique"], "why": "Another proof."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
